import json
from collections import Counter

all_failures = []
for name in ['trajectories_v5_cuda0', 'trajectories_v5_cuda1']:
    path = f'data/{name}/train.jsonl'
    with open(path) as f:
        for idx, line in enumerate(f):
            d = json.loads(line)
            d['_uid'] = f'{name}_{idx}'
            if not d.get('reward'):
                all_failures.append(d)

N = len(all_failures)

# === 1. Multi-episode check ===
print('=== Multi-Episode Structure ===')
multi_task_count = 0
tasks_per_traj = []
for d in all_failures:
    convs = d.get('conversations', [])
    task_descs = [c['content'] for c in convs if c.get('role') == 'user' and 'Your task is to:' in c.get('content', '')]
    tasks_per_traj.append(len(task_descs))
    if len(task_descs) > 1:
        multi_task_count += 1

print(f'Multi-task trajectories: {multi_task_count}/{N}')
print(f'Tasks-per-trajectory distribution: {Counter(tasks_per_traj)}')
print()

# === 2. "finish" / completion signal failures ===
print('=== Completion Signal Failures ===')
finish_count = 0
finish_patterns = Counter()
for d in all_failures:
    convs = d.get('conversations', [])
    has_finish = False
    for c in convs:
        if c.get('role') == 'assistant':
            txt = c.get('content', '').lower()
            if 'finish' in txt and 'action' in txt.lower():
                for line in txt.split('\\n'):
                    if line.strip().lower().startswith('action:'):
                        act = line.strip()[7:].strip()
                        if 'finish' in act.lower() or 'done' in act.lower() or 'complete' in act.lower():
                            has_finish = True
                            finish_patterns[act[:50]] += 1
    if has_finish:
        finish_count += 1

print(f'Trajectories with finish/done attempts: {finish_count}/{N} ({finish_count/N*100:.1f}%)')
print(f'Top finish patterns:')
for pat, cnt in finish_patterns.most_common(10):
    print(f'  {cnt:3d}x  {pat}')
print()

# === 3. What actions cause "Nothing happened"? ===
print('=== Actions Before "Nothing happened" ===')
failed_actions = Counter()
for d in all_failures:
    convs = d.get('conversations', [])
    for i in range(1, len(convs)):
        if 'Nothing happens' in convs[i].get('content', '') or 'Nothing happened' in convs[i].get('content', ''):
            # Previous assistant action
            if i > 0 and convs[i-1].get('role') == 'assistant':
                txt = convs[i-1]['content']
                for line in txt.split('\\n'):
                    if line.strip().startswith('Action:'):
                        act = line.strip()[7:].strip()
                        # Generalize: replace specific object names
                        failed_actions[act[:60]] += 1

print('Top 15 actions that get "Nothing happened":')
for act, cnt in failed_actions.most_common(15):
    print(f'  {cnt:3d}x  {act}')
print()

# === 4. Last 3 actions of pure logic failures (no parse, no loop, no exhaust) ===
print('=== Pure Logic Failures (no parse/loop/exhaust) - Last actions ===')
shown = 0
for d in all_failures:
    convs = d.get('conversations', [])
    nc = sum(1 for c in convs if 'Nothing happens' in c.get('content', '') or 'Nothing happened' in c.get('content', ''))
    if nc >= 3:
        continue  # parse failure

    actions = [c.get('content', '').strip() for c in convs if c.get('role') == 'assistant']
    has_loop = False
    for i in range(len(actions) - 2):
        if actions[i] == actions[i+1] == actions[i+2] and actions[i]:
            has_loop = True
            break
    if has_loop:
        continue

    go_to_count = sum(1 for a in actions if 'go to' in a.lower())
    if go_to_count >= 25:
        continue

    # Pure logic failure
    if shown < 5:
        # Get last task description
        task_desc = ''
        for c in convs:
            if c.get('role') == 'user' and 'Your task is to:' in c.get('content', ''):
                task_desc = c['content'].split('Your task is to:')[-1].strip().split('\\n')[0]

        last_actions = []
        for c in convs[-10:]:
            if c.get('role') == 'assistant':
                for line in c['content'].split('\\n'):
                    if line.strip().startswith('Action:'):
                        last_actions.append(line.strip()[7:].strip()[:60])

        print(f'\n  uid={d["_uid"]}, type={d.get("task_type")}, nothing={nc}')
        print(f'  Last task: {task_desc[:80]}')
        print(f'  Last actions: {last_actions[-5:]}')
        shown += 1

if shown == 0:
    print('  (none found)')
PYEOF
